const topics=[{"id":"q1","day":1,"title":"C# · Interface vs Abstract Class","concept":"An interface defines a contract; an abstract class supplies shared state and behavior.","ar":"الـ interface عقد، والـ abstract class مناسبة لو فيه state أو logic مشترك. C# يدعم تنفيذ أكثر من interface لكن وراثة class واحدة.","question":"When would you choose an abstract class?","answer":"When related classes share implementation or state; use interfaces for independent contracts.","code":"abstract class Worker { public string Name {get;set;} = \"\"; public abstract void Run(); }\ninterface ILogger { void Log(string message); }"},{"id":"q2","day":1,"title":"C# · Garbage Collection & Dispose","concept":"GC reclaims unreachable managed objects nondeterministically. Dispose releases owned resources deterministically.","ar":"Dispose لا تحذف الـ object من الـ heap فورًا؛ بتقفل resources زي file handles. الـ finalizer احتياطي وغير مضمون التوقيت.","question":"Does Dispose free managed memory immediately?","answer":"No. Dispose runs resource cleanup, while GC later reclaims memory when the object is unreachable.","code":"using var file = File.OpenRead(\"sample.txt\");\n// Dispose runs when the scope exits."},{"id":"q3","day":1,"title":"Async/Await & ThreadPool","concept":"Awaiting async I/O generally frees the request thread while the operation is pending; it does not imply a new thread.","ar":"async/await مش معناها Thread جديدة ولا تلقائيًا أسرع؛ مهم في I/O scalability.","question":"How does await improve ASP.NET Core scalability?","answer":"It avoids blocking a request thread while waiting for asynchronous I/O.","code":"var order = await db.Orders.FindAsync(id, ct);"},{"id":"q4","day":1,"title":"ASP.NET Core · Middleware & DI","concept":"Middleware runs in registration order. Scoped services live within a request scope; singleton services live for the app.","ar":"ترتيب middleware مهم. متحقنش Scoped dependency مباشرة في Singleton.","question":"Can a singleton constructor depend on DbContext?","answer":"Not directly: DbContext is normally scoped, so inject a scope factory if a background singleton needs a context.","code":"builder.Services.AddScoped<IOrderService, OrderService>();\napp.UseAuthentication();\napp.UseAuthorization();"},{"id":"q5","day":1,"title":"EF Core · Query Performance","concept":"Project only required columns, avoid N+1 queries, paginate and inspect generated SQL.","ar":"Select على DTO أنسب للقراءة لما محتاج أعمدة قليلة؛ AsNoTracking يقلل tracking overhead.","question":"Include or Select for a read-only order list?","answer":"Prefer Select into a DTO when only a few fields are needed.","code":"var items = await db.Orders.AsNoTracking()\n .Select(x => new { x.Id, Customer=x.Customer.Name })\n .Take(50).ToListAsync(ct);"},{"id":"q6","day":1,"title":"SQL Server · Indexes & Transactions","concept":"Indexes speed selective reads but cost write overhead; transactions ensure atomic changes.","ar":"راجع Composite Indexes وExecution Plans وIsolation Levels والـ deadlocks.","question":"How do you investigate a slow query?","answer":"Capture the actual execution plan and metrics, assess filters, joins, indexes and row counts before changing the query.","code":"CREATE INDEX IX_Orders_CompanyId_CreatedAt\nON Orders (CompanyId, CreatedAt);"},{"id":"q7","day":2,"title":"Angular · RxJS & Components","concept":"Observables represent streams; switchMap cancels prior inner subscriptions and is useful for searches.","ar":"switchMap مناسب للبحث المتكرر، بينما mergeMap يسمح بتنفيذ عمليات متوازية.","question":"When is switchMap preferable to mergeMap?","answer":"For search requests where only the latest result matters.","code":"results$ = search$.pipe(\n debounceTime(300), distinctUntilChanged(),\n switchMap(term => this.http.get('/api/search', { params: { term } }))\n);"},{"id":"q8","day":2,"title":"Angular · Forms & Interceptors","concept":"Reactive Forms model form state explicitly. Interceptors centralize request headers and response handling.","ar":"استخدم Validators، وتعامل مع الـ errors، ومتعتبرش Guards بديل للـ backend authorization.","question":"Can a route guard secure an API?","answer":"No. It improves UI navigation only; authorization must also be enforced on the server.","code":"const form = new FormGroup({\n name: new FormControl('', {nonNullable:true,validators:[Validators.required]})\n});"},{"id":"q9","day":2,"title":"Redis · Distributed Caching","concept":"Cache-aside reads the cache first and stores database results on a miss; TTL and invalidation prevent stale data lingering.","ar":"Redis ترفع أداء القراءة لكن محتاجة TTL وInvalidation. المفاتيح في multi-tenant لازم تحتوي TenantId.","question":"How do you avoid cross-tenant cache leaks?","answer":"Include tenant identity in every cache key and validate tenant authorization before using data.","code":"var key = $\"tenant:{tenantId}:orders:{orderId}\";\nvar json = await redis.StringGetAsync(key);"},{"id":"q10","day":2,"title":"Redis · Locks & Stampede","concept":"Distributed locks coordinate competing instances; use bounded leases and safe ownership-based unlock.","ar":"الـ distributed lock تحتاج TTL وtoken للتحقق من الملكية. راجع cache stampede وrace conditions.","question":"Why isn't SETNX alone a complete lock solution?","answer":"A lock needs expiry and ownership-aware release to avoid stale locks and deleting another owner's lock.","code":"SET resource:lock unique-token NX PX 30000"},{"id":"q11","day":2,"title":"Multi-Tenancy · Shared Schema","concept":"Shared tables use TenantId/CompanyId plus authorized tenant scoping at every data boundary.","ar":"Global Query Filters تساعد لكنها مش بديل عن authorization، مع اختبارات عزل tenants والـ unique indexes.","question":"What prevents Tenant A accessing Tenant B's records?","answer":"Resolve and authorize tenant identity server-side and enforce scoped queries and writes consistently.","code":"modelBuilder.Entity<Order>().HasQueryFilter(x => x.CompanyId == tenantId);"},{"id":"q12","day":2,"title":"Multi-Tenancy · Database per Tenant","concept":"Each tenant has its own database, improving isolation with added migration and operational complexity.","ar":"Database per Tenant أعلى في العزل لكن إدارة connections وmigrations وbackups أصعب.","question":"How would you choose between shared and separate databases?","answer":"Balance isolation, compliance, operating cost, scale and per-tenant customization.","code":"// Resolve tenant from authenticated context;\n// select an allowlisted connection string server-side."},{"id":"q13","day":2,"title":"Security · JWT / SSO","concept":"JWT validates identity claims; OAuth 2.0 concerns delegated authorization and OpenID Connect adds authentication.","ar":"احذر من تخزين secrets في الواجهة؛ Validate signature, issuer, audience, expiry والـ permissions.","question":"Is decoding a JWT the same as validating it?","answer":"No. The API must verify cryptographic signature and expected issuer, audience and lifetime.","code":"app.UseAuthentication();\napp.UseAuthorization();"},{"id":"q14","day":2,"title":"Architecture · Clean Architecture & CQRS","concept":"Keep domain rules independent of infrastructure; CQRS can separate read and write models when complexity warrants it.","ar":"مش كل مشروع يحتاج CQRS أو Microservices؛ اشرح trade-offs بدل الحفظ.","question":"When is CQRS unnecessary?","answer":"For simple CRUD with little complexity, CQRS adds indirection without sufficient benefit.","code":"// Domain -> Application -> Infrastructure adapters\n// Depend inward on abstractions."},{"id":"q15","day":3,"title":"Live Coding · CRUD API","concept":"Create endpoints with validation, DTOs, persistence and correct HTTP outcomes.","ar":"المهم تكتب كود شغال وتشرح error handling وpagination وasync مع cancellation.","question":"What would you implement first in an API coding exercise?","answer":"Clarify requirements, model a small vertical slice, then run and test it.","code":"app.MapGet(\"/orders/{id:int}\", async (int id, AppDb db) =>\n await db.Orders.FindAsync(id) is { } x ? Results.Ok(x) : Results.NotFound());"},{"id":"q16","day":3,"title":"Live Coding · SQL & Debugging","concept":"Use joins, aggregations, transaction boundaries, and verify plans for performance issues.","ar":"حل SQL بكتابة query وتشغيلها مش مجرد وصف نظري. راجع N+1 وNULL وduplicate rows.","question":"Find order counts for each customer.","answer":"Group by customer ID and count joined orders; check whether customers with zero orders must be included.","code":"SELECT c.Id, COUNT(o.Id) AS OrderCount\nFROM Customers c LEFT JOIN Orders o ON o.CustomerId=c.Id\nGROUP BY c.Id;"},{"id":"q17","day":3,"title":"Testing, Git & Docker","concept":"Unit tests isolate logic, integration tests verify dependencies and HTTP behavior; use Git to explain changes.","ar":"اعرف unit/integration والـ dependency mocking، Dockerfile وCI/CD basics.","question":"What should an integration test verify?","answer":"The collaboration of components and infrastructure boundaries, such as API plus test database.","code":"// Arrange -> Act -> Assert\n// Run the API and assert its HTTP response."},{"id":"q18","day":3,"title":"HR · Technical Storytelling","concept":"Use STAR: situation, task, action, result. Explain your actual ownership and measurable outcomes.","ar":"استخدم أمثلة CAFM الحقيقية: Dapper performance، SignalR، Redis وMulti-Tenancy بدون أرقام غير مؤكدة.","question":"Tell me about a difficult performance issue.","answer":"Describe the slow endpoint, profiling evidence, selected improvement, validation and outcome.","code":"// Prepare a 60-second STAR answer in English."},{"id":"advanced-1","day":1,"title":"C# · Value vs Reference Types","concept":"The struct value is copied by default, while a class variable holds a reference copied by value.","ar":"مراجعة سريعة: The struct value is copied by default, while a class variable holds a reference copied by value. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What happens when you pass a struct to a method?","answer":"The struct value is copied by default, while a class variable holds a reference copied by value.","code":"struct Count { public int Value; }\nvoid Inc(Count n) => n.Value++;\nvar x=new Count{Value=1}; Inc(x); // x.Value remains 1"},{"id":"advanced-2","day":1,"title":"C# · Boxing & Unboxing","concept":"Boxing copies a value type into an object on the heap; frequent boxing adds allocations and pressure on GC.","ar":"مراجعة سريعة: Boxing copies a value type into an object on the heap; frequent boxing adds allocations and pressure on GC. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why is boxing expensive?","answer":"Boxing copies a value type into an object on the heap; frequent boxing adds allocations and pressure on GC.","code":"int n=5; object boxed=n; int back=(int)boxed;"},{"id":"advanced-3","day":1,"title":"C# · String Immutability","concept":"When concatenating many pieces in a loop, because repeated string concatenation allocates new immutable strings.","ar":"مراجعة سريعة: When concatenating many pieces in a loop, because repeated string concatenation allocates new immutable strings. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When would you use StringBuilder?","answer":"When concatenating many pieces in a loop, because repeated string concatenation allocates new immutable strings.","code":"var sb=new StringBuilder(); foreach(var x in values) sb.Append(x);"},{"id":"advanced-4","day":1,"title":"C# · Records","concept":"Records provide value-oriented equality and with-expression copying by default; classes use reference equality unless overridden.","ar":"مراجعة سريعة: Records provide value-oriented equality and with-expression copying by default; classes use reference equality unless overridden. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How does a record differ from a normal class?","answer":"Records provide value-oriented equality and with-expression copying by default; classes use reference equality unless overridden.","code":"record User(int Id,string Name);\nvar updated=new User(1,\"A\") with {Name=\"B\"};"},{"id":"advanced-5","day":1,"title":"C# · Generics & Constraints","concept":"Constraints express supported operations at compile time and make reusable type-safe APIs.","ar":"مراجعة سريعة: Constraints express supported operations at compile time and make reusable type-safe APIs. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why use generic constraints?","answer":"Constraints express supported operations at compile time and make reusable type-safe APIs.","code":"void Save<T>(T item) where T: IEntity { Console.WriteLine(item.Id); }"},{"id":"advanced-6","day":1,"title":"C# · Delegates & Events","concept":"An event limits external code to subscribing/unsubscribing; only the declaring type normally raises it.","ar":"مراجعة سريعة: An event limits external code to subscribing/unsubscribing; only the declaring type normally raises it. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why use events rather than expose a delegate field?","answer":"An event limits external code to subscribing/unsubscribing; only the declaring type normally raises it.","code":"public event EventHandler? Updated;\nvoid Notify()=>Updated?.Invoke(this,EventArgs.Empty);"},{"id":"advanced-7","day":1,"title":"C# · IEnumerable vs IQueryable","concept":"IQueryable builds an expression translated to SQL when enumerated; IEnumerable in-memory operators execute locally.","ar":"مراجعة سريعة: IQueryable builds an expression translated to SQL when enumerated; IEnumerable in-memory operators execute locally. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When does a query execute in EF Core?","answer":"IQueryable builds an expression translated to SQL when enumerated; IEnumerable in-memory operators execute locally.","code":"var q=db.Orders.Where(x=>x.Total>100);\nvar data=await q.ToListAsync();"},{"id":"advanced-8","day":1,"title":"C# · Deferred Execution","concept":"Many LINQ queries execute on enumeration; repeating enumeration can repeat expensive work.","ar":"مراجعة سريعة: Many LINQ queries execute on enumeration; repeating enumeration can repeat expensive work. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What is deferred execution and what can go wrong?","answer":"Many LINQ queries execute on enumeration; repeating enumeration can repeat expensive work.","code":"var q=source.Where(x=>x.Active);\nvar cached=q.ToList();"},{"id":"advanced-9","day":1,"title":"C# · Exception Handling","concept":"No. Handle expected failures, log context, and preserve stack traces by using throw rather than throw ex.","ar":"مراجعة سريعة: No. Handle expected failures, log context, and preserve stack traces by using throw rather than throw ex. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Should you catch Exception and ignore it?","answer":"No. Handle expected failures, log context, and preserve stack traces by using throw rather than throw ex.","code":"catch(Exception ex){logger.LogError(ex,\"Request failed\");throw;}"},{"id":"advanced-10","day":1,"title":"C# · Dictionary & HashSet","concept":"For membership checks and uniqueness, a HashSet generally offers average O(1) lookup versus linear List.Contains.","ar":"مراجعة سريعة: For membership checks and uniqueness, a HashSet generally offers average O(1) lookup versus linear List.Contains. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When would you choose HashSet rather than List?","answer":"For membership checks and uniqueness, a HashSet generally offers average O(1) lookup versus linear List.Contains.","code":"var ids=new HashSet<int>(orders.Select(o=>o.Id));"},{"id":"advanced-11","day":1,"title":"C# · Finalizers & SafeHandle","concept":"SafeHandle encapsulates native handle lifetime and uses framework-tested finalization behavior.","ar":"مراجعة سريعة: SafeHandle encapsulates native handle lifetime and uses framework-tested finalization behavior. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why prefer SafeHandle over writing a finalizer?","answer":"SafeHandle encapsulates native handle lifetime and uses framework-tested finalization behavior.","code":"using var stream=File.OpenRead(\"data.txt\");"},{"id":"advanced-12","day":1,"title":"C# · GC Generations","concept":"Objects surviving collections can be promoted; long-lived retention increases higher-generation collection costs.","ar":"مراجعة سريعة: Objects surviving collections can be promoted; long-lived retention increases higher-generation collection costs. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What causes objects to be promoted to Gen 1 or Gen 2?","answer":"Objects surviving collections can be promoted; long-lived retention increases higher-generation collection costs.","code":"// Profile allocations and retained references before forcing GC."},{"id":"advanced-13","day":1,"title":"C# · IDisposable vs IAsyncDisposable","concept":"When the resource implements asynchronous disposal and cleanup can perform async I/O.","ar":"مراجعة سريعة: When the resource implements asynchronous disposal and cleanup can perform async I/O. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When is await using appropriate?","answer":"When the resource implements asynchronous disposal and cleanup can perform async I/O.","code":"await using var stream=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.None,4096,useAsync:true);"},{"id":"advanced-14","day":1,"title":"Async · Task.WhenAll","concept":"For independent asynchronous operations that can run concurrently; avoid sharing a DbContext concurrently.","ar":"مراجعة سريعة: For independent asynchronous operations that can run concurrently; avoid sharing a DbContext concurrently. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When would you use Task.WhenAll?","answer":"For independent asynchronous operations that can run concurrently; avoid sharing a DbContext concurrently.","code":"var results=await Task.WhenAll(GetAAsync(),GetBAsync());"},{"id":"advanced-15","day":1,"title":"Async · CancellationToken","concept":"Pass the request cancellation token to downstream async calls and honor cancellation.","ar":"مراجعة سريعة: Pass the request cancellation token to downstream async calls and honor cancellation. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do you cancel a long API request?","answer":"Pass the request cancellation token to downstream async calls and honor cancellation.","code":"app.MapGet(\"/items\",(AppDb db,CancellationToken ct)=>db.Items.ToListAsync(ct));"},{"id":"advanced-16","day":1,"title":"Async · Deadlocks & Blocking","concept":"It blocks a thread and can cause thread-pool starvation; sync-context deadlocks occur in some other environments.","ar":"مراجعة سريعة: It blocks a thread and can cause thread-pool starvation; sync-context deadlocks occur in some other environments. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why avoid .Result in ASP.NET Core?","answer":"It blocks a thread and can cause thread-pool starvation; sync-context deadlocks occur in some other environments.","code":"var value=await service.LoadAsync(); // not service.LoadAsync().Result"},{"id":"advanced-17","day":1,"title":"Async · CPU vs I/O Bound","concept":"It can offload CPU-bound work; don't wrap already asynchronous database or HTTP calls in Task.Run.","ar":"مراجعة سريعة: It can offload CPU-bound work; don't wrap already asynchronous database or HTTP calls in Task.Run. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When should you use Task.Run?","answer":"It can offload CPU-bound work; don't wrap already asynchronous database or HTTP calls in Task.Run.","code":"var hash=await Task.Run(()=>ExpensiveHash(data),ct);"},{"id":"advanced-18","day":1,"title":"OOP · Encapsulation","concept":"Encapsulation protects state and invariants; abstraction exposes only relevant behavior.","ar":"مراجعة سريعة: Encapsulation protects state and invariants; abstraction exposes only relevant behavior. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How is encapsulation different from abstraction?","answer":"Encapsulation protects state and invariants; abstraction exposes only relevant behavior.","code":"class Account { public decimal Balance {get;private set;} public void Deposit(decimal x){if(x<=0)throw new ArgumentException();Balance+=x;} }"},{"id":"advanced-19","day":1,"title":"SOLID · SRP & OCP","concept":"Separate responsibilities by reasons to change; extend behaviors through abstractions rather than editing giant conditional blocks.","ar":"مراجعة سريعة: Separate responsibilities by reasons to change; extend behaviors through abstractions rather than editing giant conditional blocks. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Give an example of SRP and OCP.","answer":"Separate responsibilities by reasons to change; extend behaviors through abstractions rather than editing giant conditional blocks.","code":"interface IDiscount{decimal Apply(decimal amount);}"},{"id":"advanced-20","day":1,"title":"SOLID · LSP / ISP / DIP","concept":"Depending on abstractions improves testability and honors dependency inversion.","ar":"مراجعة سريعة: Depending on abstractions improves testability and honors dependency inversion. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why shouldn't application services instantiate infrastructure clients?","answer":"Depending on abstractions improves testability and honors dependency inversion.","code":"class BillingService(IPaymentGateway gateway) { }"},{"id":"advanced-21","day":1,"title":"Design Patterns · Factory","concept":"When object construction varies by input or has complex dependencies; keep creation decisions centralized.","ar":"مراجعة سريعة: When object construction varies by input or has complex dependencies; keep creation decisions centralized. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When should you use the Factory pattern?","answer":"When object construction varies by input or has complex dependencies; keep creation decisions centralized.","code":"IExporter Create(string type)=>type switch {\"csv\"=>new CsvExporter(),\"pdf\"=>new PdfExporter(),_=>throw new NotSupportedException()};"},{"id":"advanced-22","day":1,"title":"Design Patterns · Strategy","concept":"Strategy encapsulates interchangeable algorithms; a factory chooses or creates an implementation.","ar":"مراجعة سريعة: Strategy encapsulates interchangeable algorithms; a factory chooses or creates an implementation. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How is Strategy different from Factory?","answer":"Strategy encapsulates interchangeable algorithms; a factory chooses or creates an implementation.","code":"interface IPricingStrategy {decimal Calculate(Order order);}"},{"id":"advanced-23","day":1,"title":"Design Patterns · Decorator","concept":"Wrap a service with the same interface and intercept calls without modifying the core implementation.","ar":"مراجعة سريعة: Wrap a service with the same interface and intercept calls without modifying the core implementation. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How can a decorator add caching?","answer":"Wrap a service with the same interface and intercept calls without modifying the core implementation.","code":"class CachedReader(IReader inner,ICache cache):IReader { /* cache then delegate */ }"},{"id":"advanced-24","day":1,"title":"API · HTTP Status Codes","concept":"400 invalid request; 401 unauthenticated; 403 unauthorized; 404 missing resource; 409 conflict.","ar":"مراجعة سريعة: 400 invalid request; 401 unauthenticated; 403 unauthorized; 404 missing resource; 409 conflict. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When return 400, 401, 403, 404 or 409?","answer":"400 invalid request; 401 unauthenticated; 403 unauthorized; 404 missing resource; 409 conflict.","code":"return Results.Conflict(new { message=\"Version mismatch\" });"},{"id":"advanced-25","day":1,"title":"API · Pagination","concept":"To bound rows, memory and response size; use stable ordering and indexed keys.","ar":"مراجعة سريعة: To bound rows, memory and response size; use stable ordering and indexed keys. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why paginate at database level?","answer":"To bound rows, memory and response size; use stable ordering and indexed keys.","code":"var page=await db.Orders.OrderBy(x=>x.Id).Skip(skip).Take(50).ToListAsync();"},{"id":"advanced-26","day":1,"title":"API · Middleware vs Filters","concept":"Middleware works around the whole request pipeline; MVC action filters operate in MVC action execution.","ar":"مراجعة سريعة: Middleware works around the whole request pipeline; MVC action filters operate in MVC action execution. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What's the difference between middleware and action filters?","answer":"Middleware works around the whole request pipeline; MVC action filters operate in MVC action execution.","code":"app.Use(async(ctx,next)=>{ await next(ctx); });"},{"id":"advanced-27","day":1,"title":"API · Validation & ProblemDetails","concept":"Validate inputs and return consistent structured error responses, often ValidationProblem/ProblemDetails.","ar":"مراجعة سريعة: Validate inputs and return consistent structured error responses, often ValidationProblem/ProblemDetails. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How should validation errors be returned?","answer":"Validate inputs and return consistent structured error responses, often ValidationProblem/ProblemDetails.","code":"return Results.ValidationProblem(new Dictionary<string,string[]>{{\"Name\",[\"Required\"]}});"},{"id":"advanced-28","day":1,"title":"API · Authentication vs Authorization","concept":"Authentication identifies the caller; authorization decides what the caller can do.","ar":"مراجعة سريعة: Authentication identifies the caller; authorization decides what the caller can do. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What's the difference?","answer":"Authentication identifies the caller; authorization decides what the caller can do.","code":"app.MapGet(\"/admin\",Handler).RequireAuthorization(\"AdminsOnly\");"},{"id":"advanced-29","day":1,"title":"EF Core · N+1 Query","concept":"Many per-row queries cause N+1; project required related data or load related data in controlled batches.","ar":"مراجعة سريعة: Many per-row queries cause N+1; project required related data or load related data in controlled batches. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do you recognize and fix N+1?","answer":"Many per-row queries cause N+1; project required related data or load related data in controlled batches.","code":"var data=await db.Orders.Select(o=>new {o.Id,Customer=o.Customer.Name}).ToListAsync();"},{"id":"advanced-30","day":1,"title":"EF Core · Optimistic Concurrency","concept":"Use a concurrency token, catch DbUpdateConcurrencyException and resolve conflicts.","ar":"مراجعة سريعة: Use a concurrency token, catch DbUpdateConcurrencyException and resolve conflicts. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What happens if two users update the same row?","answer":"Use a concurrency token, catch DbUpdateConcurrencyException and resolve conflicts.","code":"modelBuilder.Entity<Order>().Property(x=>x.RowVersion).IsRowVersion();"},{"id":"advanced-31","day":1,"title":"EF Core · Split Queries","concept":"It may avoid cartesian explosion with multiple collection includes but requires multiple SQL round trips.","ar":"مراجعة سريعة: It may avoid cartesian explosion with multiple collection includes but requires multiple SQL round trips. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When is AsSplitQuery useful?","answer":"It may avoid cartesian explosion with multiple collection includes but requires multiple SQL round trips.","code":"var orders=await db.Orders.Include(x=>x.Items).AsSplitQuery().ToListAsync();"},{"id":"advanced-32","day":1,"title":"EF Core · SaveChanges & Transactions","concept":"Each call commonly uses its own transaction; use explicit transaction when atomicity across calls is required.","ar":"مراجعة سريعة: Each call commonly uses its own transaction; use explicit transaction when atomicity across calls is required. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Are multiple SaveChanges calls one transaction?","answer":"Each call commonly uses its own transaction; use explicit transaction when atomicity across calls is required.","code":"await using var tx=await db.Database.BeginTransactionAsync(ct); /* writes */ await db.SaveChangesAsync(ct); await tx.CommitAsync(ct);"},{"id":"advanced-33","day":1,"title":"SQL · JOIN vs EXISTS","concept":"EXISTS expresses an existence test without multiplying outer rows from matching records.","ar":"مراجعة سريعة: EXISTS expresses an existence test without multiplying outer rows from matching records. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When might EXISTS be more appropriate than JOIN?","answer":"EXISTS expresses an existence test without multiplying outer rows from matching records.","code":"SELECT * FROM Customers c WHERE EXISTS(SELECT 1 FROM Orders o WHERE o.CustomerId=c.Id);"},{"id":"advanced-34","day":1,"title":"SQL · CTE & Window Functions","concept":"ROW_NUMBER partitions by customer and orders descending, then filter to row 1.","ar":"مراجعة سريعة: ROW_NUMBER partitions by customer and orders descending, then filter to row 1. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do you find latest order per customer?","answer":"ROW_NUMBER partitions by customer and orders descending, then filter to row 1.","code":"WITH x AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY CustomerId ORDER BY CreatedAt DESC,Id DESC) rn FROM Orders) SELECT * FROM x WHERE rn=1;"},{"id":"advanced-35","day":1,"title":"SQL · Isolation Levels","concept":"Reading uncommitted data that another transaction may roll back; isolation controls anomalies.","ar":"مراجعة سريعة: Reading uncommitted data that another transaction may roll back; isolation controls anomalies. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What's a dirty read?","answer":"Reading uncommitted data that another transaction may roll back; isolation controls anomalies.","code":"SET TRANSACTION ISOLATION LEVEL READ COMMITTED;"},{"id":"advanced-36","day":1,"title":"SQL · Deadlocks","concept":"Keep transactions short, access resources consistently, index predicates and retry deadlock victims carefully.","ar":"مراجعة سريعة: Keep transactions short, access resources consistently, index predicates and retry deadlock victims carefully. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do you mitigate SQL deadlocks?","answer":"Keep transactions short, access resources consistently, index predicates and retry deadlock victims carefully.","code":"-- Inspect deadlock graph and query plans before optimizing."},{"id":"advanced-37","day":1,"title":"SQL · Stored Procedures","concept":"They centralize SQL logic and permissions but can increase deployment coupling and complicate testing.","ar":"مراجعة سريعة: They centralize SQL logic and permissions but can increase deployment coupling and complicate testing. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What are pros and cons of stored procedures?","answer":"They centralize SQL logic and permissions but can increase deployment coupling and complicate testing.","code":"CREATE PROCEDURE dbo.GetOrders @CompanyId int AS BEGIN SELECT Id FROM Orders WHERE CompanyId=@CompanyId END;"},{"id":"advanced-38","day":1,"title":"SQL · Dapper vs EF Core","concept":"For precise SQL control on performance-critical reads; EF Core is useful for change tracking and domain persistence.","ar":"مراجعة سريعة: For precise SQL control on performance-critical reads; EF Core is useful for change tracking and domain persistence. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When would you use Dapper?","answer":"For precise SQL control on performance-critical reads; EF Core is useful for change tracking and domain persistence.","code":"var rows=await connection.QueryAsync<OrderDto>(\"SELECT Id, Total FROM Orders WHERE CompanyId=@id\",new{id});"},{"id":"advanced-39","day":1,"title":"Database · Oracle vs SQL Server","concept":"SQL dialect, data types, identity/sequence behavior, pagination and provider-specific capabilities differ.","ar":"مراجعة سريعة: SQL dialect, data types, identity/sequence behavior, pagination and provider-specific capabilities differ. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What changes when targeting Oracle?","answer":"SQL dialect, data types, identity/sequence behavior, pagination and provider-specific capabilities differ.","code":"-- Verify provider-specific SQL; do not assume T-SQL syntax works in Oracle."},{"id":"advanced-40","day":2,"title":"Angular · Lifecycle Hooks","concept":"Initialize component state/subscriptions in ngOnInit and clean up long-lived resources in ngOnDestroy.","ar":"مراجعة سريعة: Initialize component state/subscriptions in ngOnInit and clean up long-lived resources in ngOnDestroy. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What belongs in ngOnInit vs ngOnDestroy?","answer":"Initialize component state/subscriptions in ngOnInit and clean up long-lived resources in ngOnDestroy.","code":"ngOnInit(){ this.load(); } ngOnDestroy(){ this.subscription?.unsubscribe(); }"},{"id":"advanced-41","day":2,"title":"Angular · Change Detection","concept":"OnPush narrows update triggers; prefer immutable state changes, signals and async pipe for predictable rendering.","ar":"مراجعة سريعة: OnPush narrows update triggers; prefer immutable state changes, signals and async pipe for predictable rendering. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What does OnPush change?","answer":"OnPush narrows update triggers; prefer immutable state changes, signals and async pipe for predictable rendering.","code":"changeDetection: ChangeDetectionStrategy.OnPush"},{"id":"advanced-42","day":2,"title":"Angular · Signals","concept":"Computed derives memoized state reactively from other signals.","ar":"مراجعة سريعة: Computed derives memoized state reactively from other signals. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do computed signals work?","answer":"Computed derives memoized state reactively from other signals.","code":"count=signal(0); doubled=computed(()=>this.count()*2);"},{"id":"advanced-43","day":2,"title":"Angular · Subject vs BehaviorSubject","concept":"BehaviorSubject requires and exposes a current value to new subscribers; Subject doesn't replay one.","ar":"مراجعة سريعة: BehaviorSubject requires and exposes a current value to new subscribers; Subject doesn't replay one. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How is BehaviorSubject different?","answer":"BehaviorSubject requires and exposes a current value to new subscribers; Subject doesn't replay one.","code":"const selected$=new BehaviorSubject<number|null>(null);"},{"id":"advanced-44","day":2,"title":"Angular · switchMap vs concatMap vs exhaustMap","concept":"exhaustMap can ignore duplicate clicks while pending; concatMap queues; switchMap switches to latest.","ar":"مراجعة سريعة: exhaustMap can ignore duplicate clicks while pending; concatMap queues; switchMap switches to latest. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Which RxJS mapping operator fits form submission?","answer":"exhaustMap can ignore duplicate clicks while pending; concatMap queues; switchMap switches to latest.","code":"saveClicks$.pipe(exhaustMap(()=>api.save(form.value))).subscribe();"},{"id":"advanced-45","day":2,"title":"Angular · takeUntilDestroyed","concept":"Prefer async pipe or takeUntilDestroyed for managed subscriptions, while avoiding unnecessary manual subscriptions.","ar":"مراجعة سريعة: Prefer async pipe or takeUntilDestroyed for managed subscriptions, while avoiding unnecessary manual subscriptions. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do you avoid subscription leaks?","answer":"Prefer async pipe or takeUntilDestroyed for managed subscriptions, while avoiding unnecessary manual subscriptions.","code":"source$.pipe(takeUntilDestroyed(this.destroyRef)).subscribe(x=>this.value=x);"},{"id":"advanced-46","day":2,"title":"Angular · Interceptors","concept":"Use an HTTP interceptor and clone immutable requests; server must still validate every token.","ar":"مراجعة سريعة: Use an HTTP interceptor and clone immutable requests; server must still validate every token. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do you attach bearer tokens?","answer":"Use an HTTP interceptor and clone immutable requests; server must still validate every token.","code":"return next(req.clone({setHeaders:{Authorization:'Bearer '+token}}));"},{"id":"advanced-47","day":2,"title":"Angular · Route Guards","concept":"A guard only controls client navigation; backend must enforce actual authorization.","ar":"مراجعة سريعة: A guard only controls client navigation; backend must enforce actual authorization. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Does a guard enforce authorization?","answer":"A guard only controls client navigation; backend must enforce actual authorization.","code":"{path:'admin',canActivate:[authGuard],loadComponent:()=>import('./admin').then(x=>x.Admin)}"},{"id":"advanced-48","day":2,"title":"Angular · Lazy Loading","concept":"Load feature code on demand to reduce initial bundle size.","ar":"مراجعة سريعة: Load feature code on demand to reduce initial bundle size. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why use lazy loading?","answer":"Load feature code on demand to reduce initial bundle size.","code":"{path:'reports',loadChildren:()=>import('./reports/routes').then(m=>m.routes)}"},{"id":"advanced-49","day":2,"title":"Angular · Reactive Form Async Validation","concept":"When validation requires external async checks, such as username availability, with appropriate debounce at service level.","ar":"مراجعة سريعة: When validation requires external async checks, such as username availability, with appropriate debounce at service level. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When use an async validator?","answer":"When validation requires external async checks, such as username availability, with appropriate debounce at service level.","code":"new FormControl('',{asyncValidators:[uniqueNameValidator]});"},{"id":"advanced-50","day":2,"title":"TypeScript · any vs unknown","concept":"unknown forces type narrowing before use, whereas any disables useful checks.","ar":"مراجعة سريعة: unknown forces type narrowing before use, whereas any disables useful checks. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why prefer unknown?","answer":"unknown forces type narrowing before use, whereas any disables useful checks.","code":"function parse(x:unknown){if(typeof x==='string') return x.trim();}"},{"id":"advanced-51","day":2,"title":"TypeScript · Union Types","concept":"A discriminant enables exhaustive type-safe branches for multiple states.","ar":"مراجعة سريعة: A discriminant enables exhaustive type-safe branches for multiple states. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why use a discriminated union?","answer":"A discriminant enables exhaustive type-safe branches for multiple states.","code":"type Result={kind:'ok';data:string}|{kind:'error';message:string};"},{"id":"advanced-52","day":2,"title":"Frontend · XSS & CSRF","concept":"XSS executes untrusted script; CSRF causes unwanted authenticated actions; protections differ.","ar":"مراجعة سريعة: XSS executes untrusted script; CSRF causes unwanted authenticated actions; protections differ. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do XSS and CSRF differ?","answer":"XSS executes untrusted script; CSRF causes unwanted authenticated actions; protections differ.","code":"// Keep Angular escaping enabled; use CSRF tokens for cookie-authenticated mutations."},{"id":"advanced-53","day":2,"title":"Redis · Eviction vs TTL","concept":"TTL expires keys by time; eviction removes keys based on memory pressure and configured policy.","ar":"مراجعة سريعة: TTL expires keys by time; eviction removes keys based on memory pressure and configured policy. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What is the difference between expiration and eviction?","answer":"TTL expires keys by time; eviction removes keys based on memory pressure and configured policy.","code":"SET tenant:7:config value EX 300"},{"id":"advanced-54","day":2,"title":"Redis · Cache Aside Failure","concept":"For optional read caching, degrade to the database with rate limits and visibility; for locks or correctness-critical coordination, fail safely.","ar":"مراجعة سريعة: For optional read caching, degrade to the database with rate limits and visibility; for locks or correctness-critical coordination, fail safely. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What should happen if Redis is unavailable?","answer":"For optional read caching, degrade to the database with rate limits and visibility; for locks or correctness-critical coordination, fail safely.","code":"// Catch cache-availability errors, not data-access authorization failures."},{"id":"advanced-55","day":2,"title":"Redis · Pub/Sub vs Streams","concept":"Streams support durable history and consumer groups; Pub/Sub messages aren't retained for offline subscribers.","ar":"مراجعة سريعة: Streams support durable history and consumer groups; Pub/Sub messages aren't retained for offline subscribers. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When use Redis Streams rather than Pub/Sub?","answer":"Streams support durable history and consumer groups; Pub/Sub messages aren't retained for offline subscribers.","code":"XADD events * type order-created id 31"},{"id":"advanced-56","day":2,"title":"Distributed Systems · Idempotency","concept":"Use idempotency keys with persisted request outcomes and database uniqueness constraints.","ar":"مراجعة سريعة: Use idempotency keys with persisted request outcomes and database uniqueness constraints. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How prevent duplicate order creation on retries?","answer":"Use idempotency keys with persisted request outcomes and database uniqueness constraints.","code":"CREATE UNIQUE INDEX UX_Orders_RequestKey ON Orders(CompanyId,RequestKey);"},{"id":"advanced-57","day":2,"title":"Distributed Systems · Outbox","concept":"Persist business change and event intent in the same database transaction, then publish asynchronously.","ar":"مراجعة سريعة: Persist business change and event intent in the same database transaction, then publish asynchronously. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why use the transactional outbox pattern?","answer":"Persist business change and event intent in the same database transaction, then publish asynchronously.","code":"// Transaction: INSERT Orders; INSERT OutboxEvents; COMMIT;"},{"id":"advanced-58","day":2,"title":"Distributed Systems · Eventual Consistency","concept":"Independent components may temporarily disagree but converge through reliable event processing.","ar":"مراجعة سريعة: Independent components may temporarily disagree but converge through reliable event processing. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What is eventual consistency?","answer":"Independent components may temporarily disagree but converge through reliable event processing.","code":"// Make consumer handlers idempotent and retry-safe."},{"id":"advanced-59","day":2,"title":"Distributed Systems · SignalR","concept":"For near-real-time server pushes such as progress or notifications; design authorization and scale-out.","ar":"مراجعة سريعة: For near-real-time server pushes such as progress or notifications; design authorization and scale-out. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When use SignalR over polling?","answer":"For near-real-time server pushes such as progress or notifications; design authorization and scale-out.","code":"await hub.Clients.Group($\"tenant:{tenantId}\").SendAsync(\"Updated\",payload);"},{"id":"advanced-60","day":2,"title":"Multi-Tenancy · Tenant Resolution","concept":"Resolve it from authenticated/authorized membership, not untrusted query parameters alone.","ar":"مراجعة سريعة: Resolve it from authenticated/authorized membership, not untrusted query parameters alone. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Where should TenantId come from?","answer":"Resolve it from authenticated/authorized membership, not untrusted query parameters alone.","code":"var tenantId=user.FindFirst(\"tenant_id\")?.Value; // validate tenant membership"},{"id":"advanced-61","day":2,"title":"Multi-Tenancy · Unique Indexes","concept":"Use a composite unique index containing TenantId and InvoiceNumber.","ar":"مراجعة سريعة: Use a composite unique index containing TenantId and InvoiceNumber. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How ensure unique invoice numbers per tenant?","answer":"Use a composite unique index containing TenantId and InvoiceNumber.","code":"CREATE UNIQUE INDEX UX_Invoices_Tenant_Number ON Invoices(TenantId,InvoiceNumber);"},{"id":"advanced-62","day":2,"title":"Multi-Tenancy · Tenant Migrations","concept":"Run controlled versioned migrations per tenant with monitoring, throttling, backup and rollback plans.","ar":"مراجعة سريعة: Run controlled versioned migrations per tenant with monitoring, throttling, backup and rollback plans. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do migrations work with database per tenant?","answer":"Run controlled versioned migrations per tenant with monitoring, throttling, backup and rollback plans.","code":"// Discover authorized tenant DBs; migrate in bounded batches."},{"id":"advanced-63","day":2,"title":"Architecture · CQRS & MediatR","concept":"No. CQRS is a design separation of commands and queries; MediatR is an optional in-process dispatch library.","ar":"مراجعة سريعة: No. CQRS is a design separation of commands and queries; MediatR is an optional in-process dispatch library. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Does CQRS require MediatR?","answer":"No. CQRS is a design separation of commands and queries; MediatR is an optional in-process dispatch library.","code":"public record GetOrderQuery(int Id);"},{"id":"advanced-64","day":2,"title":"Architecture · Monolith vs Microservices","concept":"When team and deployment complexity don't justify distributed boundaries; modules can still be well isolated.","ar":"مراجعة سريعة: When team and deployment complexity don't justify distributed boundaries; modules can still be well isolated. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"When is a modular monolith preferable?","answer":"When team and deployment complexity don't justify distributed boundaries; modules can still be well isolated.","code":"// Keep module interfaces explicit before extracting network services."},{"id":"advanced-65","day":2,"title":"Security · Password Storage","concept":"Use a slow, salted password-hashing algorithm such as Argon2id, bcrypt or PBKDF2; never reversible encryption for password verification.","ar":"مراجعة سريعة: Use a slow, salted password-hashing algorithm such as Argon2id, bcrypt or PBKDF2; never reversible encryption for password verification. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Should we encrypt or hash passwords?","answer":"Use a slow, salted password-hashing algorithm such as Argon2id, bcrypt or PBKDF2; never reversible encryption for password verification.","code":"// ASP.NET Core Identity provides password hashing and account management."},{"id":"advanced-66","day":2,"title":"Security · CORS","concept":"No. CORS is browser enforcement and not an API authentication or authorization boundary.","ar":"مراجعة سريعة: No. CORS is browser enforcement and not an API authentication or authorization boundary. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Does CORS prevent direct requests from Postman?","answer":"No. CORS is browser enforcement and not an API authentication or authorization boundary.","code":"app.UseCors(\"FrontendPolicy\");"},{"id":"advanced-67","day":3,"title":"Live Coding · Two Sum","concept":"Store previously seen numbers in a dictionary and look up the complement.","ar":"مراجعة سريعة: Store previously seen numbers in a dictionary and look up the complement. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do you solve Two Sum in O(n)?","answer":"Store previously seen numbers in a dictionary and look up the complement.","code":"for(int i=0;i<a.Length;i++){int k=target-a[i];if(seen.TryGetValue(k,out var j))return new[]{j,i};seen[a[i]]=i;}"},{"id":"advanced-68","day":3,"title":"Live Coding · Duplicates","concept":"Track seen values using a HashSet and collect duplicates in another set.","ar":"مراجعة سريعة: Track seen values using a HashSet and collect duplicates in another set. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do you find duplicate IDs efficiently?","answer":"Track seen values using a HashSet and collect duplicates in another set.","code":"var seen=new HashSet<int>();var dup=ids.Where(x=>!seen.Add(x)).Distinct().ToList();"},{"id":"advanced-69","day":3,"title":"Live Coding · Pagination Bug","concept":"An unstable order or data changes between reads; use stable unique ordering and consider keyset pagination.","ar":"مراجعة سريعة: An unstable order or data changes between reads; use stable unique ordering and consider keyset pagination. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why can Skip/Take produce duplicates across pages?","answer":"An unstable order or data changes between reads; use stable unique ordering and consider keyset pagination.","code":"var page=await q.Where(x=>x.Id>lastId).OrderBy(x=>x.Id).Take(50).ToListAsync();"},{"id":"advanced-70","day":3,"title":"Live Coding · Angular Search","concept":"Use debounceTime, distinctUntilChanged and switchMap with proper error handling.","ar":"مراجعة سريعة: Use debounceTime, distinctUntilChanged and switchMap with proper error handling. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do you avoid one HTTP request per keystroke?","answer":"Use debounceTime, distinctUntilChanged and switchMap with proper error handling.","code":"search.valueChanges.pipe(debounceTime(300),distinctUntilChanged(),switchMap(x=>api.search(x))).subscribe();"},{"id":"advanced-71","day":3,"title":"Testing · Unit vs Integration","concept":"Mock boundaries, not every class; integration tests verify real composition and infrastructure.","ar":"مراجعة سريعة: Mock boundaries, not every class; integration tests verify real composition and infrastructure. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What should you mock in unit tests?","answer":"Mock boundaries, not every class; integration tests verify real composition and infrastructure.","code":"// Arrange input; call pure pricing service; assert result."},{"id":"advanced-72","day":3,"title":"DevOps · Docker Multi-Stage","concept":"Keep build tools out of the runtime image to reduce size and attack surface.","ar":"مراجعة سريعة: Keep build tools out of the runtime image to reduce size and attack surface. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"Why use multi-stage Dockerfiles?","answer":"Keep build tools out of the runtime image to reduce size and attack surface.","code":"FROM mcr.microsoft.com/dotnet/sdk:8.0 AS build\n# publish...\nFROM mcr.microsoft.com/dotnet/aspnet:8.0"},{"id":"advanced-73","day":3,"title":"DevOps · CI/CD","concept":"Restore, lint/build, unit tests, dependency checks and integration tests where feasible.","ar":"مراجعة سريعة: Restore, lint/build, unit tests, dependency checks and integration tests where feasible. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"What checks should a PR pipeline run?","answer":"Restore, lint/build, unit tests, dependency checks and integration tests where feasible.","code":"dotnet test --configuration Release"},{"id":"advanced-74","day":3,"title":"Behavioral · Code Review","concept":"Explain trade-offs with evidence, ask questions, and align on maintainability and team standards.","ar":"مراجعة سريعة: Explain trade-offs with evidence, ask questions, and align on maintainability and team standards. ركّز على سبب الاختيار والـ trade-offs، واربطه بمثال عملي.","question":"How do you handle disagreement in code review?","answer":"Explain trade-offs with evidence, ask questions, and align on maintainability and team standards.","code":"// Prepare a STAR story with situation, action and outcome."},{"id":"deep-1","day":1,"title":"C# · Equality & GetHashCode","concept":"Hash-based collections rely on consistent equality/hash contracts; equal keys must hash equally.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why must equal objects have equal hash codes?","answer":"Hash-based collections rely on consistent equality/hash contracts; equal keys must hash equally.","code":"record Key(int CompanyId,int Id); var map=new Dictionary<Key,string>();"},{"id":"deep-2","day":1,"title":"C# · ref / out / in","concept":"ref passes an assignable variable by reference; out requires assignment in method; in is readonly by-reference.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do ref, out and in differ?","answer":"ref passes an assignable variable by reference; out requires assignment in method; in is readonly by-reference.","code":"void Try(out int result){result=1;}"},{"id":"deep-3","day":1,"title":"C# · Nullable Reference Types","concept":"No, nullable reference types primarily add compile-time analysis and warnings; validate boundaries at runtime.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Does string? prevent null at runtime?","answer":"No, nullable reference types primarily add compile-time analysis and warnings; validate boundaries at runtime.","code":"string? name=input; if(name is null) return;"},{"id":"deep-4","day":1,"title":"C# · Span<T>","concept":"Span<T> enables slice operations over contiguous memory without allocations but has ref-struct lifetime restrictions.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why use Span<T>?","answer":"Span<T> enables slice operations over contiguous memory without allocations but has ref-struct lifetime restrictions.","code":"ReadOnlySpan<char> s=\"abc\".AsSpan();"},{"id":"deep-5","day":1,"title":"C# · Cancellation vs Timeout","concept":"Cancellation signals abandoned work; handle OperationCanceledException distinctly, and don't blindly turn it into HTTP 500.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Is cancellation a failed operation?","answer":"Cancellation signals abandoned work; handle OperationCanceledException distinctly, and don't blindly turn it into HTTP 500.","code":"await Task.Delay(1000,ct);"},{"id":"deep-6","day":1,"title":"C# · SemaphoreSlim","concept":"To bound parallel work or protect async critical sections inside one process; it is not a distributed lock.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"When would SemaphoreSlim be useful?","answer":"To bound parallel work or protect async critical sections inside one process; it is not a distributed lock.","code":"await gate.WaitAsync(ct);try{await WorkAsync();}finally{gate.Release();}"},{"id":"deep-7","day":1,"title":"ASP.NET · Service Lifetimes","concept":"It effectively extends scoped state lifetime and risks thread-safety and stale tenant/request data.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What happens when a singleton captures scoped state?","answer":"It effectively extends scoped state lifetime and risks thread-safety and stale tenant/request data.","code":"services.AddScoped<AppDb>(); // Never inject into singleton directly."},{"id":"deep-8","day":1,"title":"ASP.NET · Options Pattern","concept":"IOptionsMonitor supports change notifications and is usable in singletons; snapshot resolves per-scope snapshots.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"When use IOptionsMonitor rather than IOptionsSnapshot?","answer":"IOptionsMonitor supports change notifications and is usable in singletons; snapshot resolves per-scope snapshots.","code":"services.Configure<MyOptions>(configuration.GetSection(\"MyOptions\"));"},{"id":"deep-9","day":1,"title":"ASP.NET · BackgroundService","concept":"Inject IServiceScopeFactory and create a new scope per execution; handle shutdown token.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How should a BackgroundService use DbContext?","answer":"Inject IServiceScopeFactory and create a new scope per execution; handle shutdown token.","code":"using var scope=scopeFactory.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();"},{"id":"deep-10","day":1,"title":"ASP.NET · Rate Limiting","concept":"Protect costly endpoints from abuse and resource exhaustion using tenant/user-appropriate policies.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why implement rate limiting?","answer":"Protect costly endpoints from abuse and resource exhaustion using tenant/user-appropriate policies.","code":"app.UseRateLimiter();"},{"id":"deep-11","day":1,"title":"ASP.NET · File Upload Safety","concept":"Enforce size limits, content validation, authorized tenant pathing and safe generated filenames.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What should you validate before storing uploads?","answer":"Enforce size limits, content validation, authorized tenant pathing and safe generated filenames.","code":"var name=Path.GetRandomFileName(); // not original user path"},{"id":"deep-12","day":1,"title":"API · Idempotent HTTP Methods","concept":"A repeated identical PUT should have the same intended effect; POST is not generally idempotent without extra handling.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Is PUT idempotent?","answer":"A repeated identical PUT should have the same intended effect; POST is not generally idempotent without extra handling.","code":"app.MapPut(\"/items/{id}\",UpdateItem);"},{"id":"deep-13","day":1,"title":"API · Optimistic Locking","concept":"If-Match with a version token makes conflicting updates detectable; return 412 where applicable.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How can ETags protect updates?","answer":"If-Match with a version token makes conflicting updates detectable; return 412 where applicable.","code":"// Require If-Match: \"version-7\" and reject stale edits."},{"id":"deep-14","day":1,"title":"API · Structured Logging","concept":"Logs can expose tokens and PII; log correlation IDs, tenant-safe context and sanitized fields.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why avoid logging sensitive request bodies?","answer":"Logs can expose tokens and PII; log correlation IDs, tenant-safe context and sanitized fields.","code":"logger.LogInformation(\"Order {OrderId} updated\",id);"},{"id":"deep-15","day":1,"title":"API · Health Checks","concept":"Readiness should reflect critical dependencies needed to serve traffic; avoid overloading dependency services.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What should readiness checks verify?","answer":"Readiness should reflect critical dependencies needed to serve traffic; avoid overloading dependency services.","code":"app.MapHealthChecks(\"/health/ready\");"},{"id":"deep-16","day":1,"title":"EF Core · ExecuteUpdate","concept":"For bulk updates without loading tracked entities; bypasses change tracker and SaveChanges flow.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"When use ExecuteUpdateAsync?","answer":"For bulk updates without loading tracked entities; bypasses change tracker and SaveChanges flow.","code":"await db.Orders.Where(x=>x.Status==0).ExecuteUpdateAsync(x=>x.SetProperty(o=>o.Status,1));"},{"id":"deep-17","day":1,"title":"EF Core · Compiled Queries","concept":"For measured hot query paths with repeated shapes, reducing compilation overhead; benchmark first.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"When are compiled queries useful?","answer":"For measured hot query paths with repeated shapes, reducing compilation overhead; benchmark first.","code":"// EF.CompileAsyncQuery(ctx => ctx.Orders.Where(x=>x.Active))"},{"id":"deep-18","day":1,"title":"EF Core · DbContext Lifetime","concept":"A DbContext tracks mutable state and doesn't support parallel operations on the same instance.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why is DbContext not thread-safe?","answer":"A DbContext tracks mutable state and doesn't support parallel operations on the same instance.","code":"await Task.WhenAll(queries.Select(q=>RunWithNewContext(q)));"},{"id":"deep-19","day":1,"title":"EF Core · Global Filters","concept":"No. They help enforce scoped reads but raw SQL, writes and disabled filters still need server-side checks.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Can global filters replace tenant authorization?","answer":"No. They help enforce scoped reads but raw SQL, writes and disabled filters still need server-side checks.","code":"db.Orders.Where(x=>x.CompanyId==tenantId);"},{"id":"deep-20","day":1,"title":"SQL · Covering Index","concept":"An INCLUDE column can cover projected data without expanding the key portion of a nonclustered index.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What is an included column?","answer":"An INCLUDE column can cover projected data without expanding the key portion of a nonclustered index.","code":"CREATE INDEX IX_Orders_Tenant ON Orders(CompanyId) INCLUDE(Total);"},{"id":"deep-21","day":1,"title":"SQL · SARGability","concept":"Applying functions to indexed columns may block efficient seeks; use range predicates.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why might YEAR(CreatedAt)=2026 be slow?","answer":"Applying functions to indexed columns may block efficient seeks; use range predicates.","code":"WHERE CreatedAt >= '20260101' AND CreatedAt < '20270101'"},{"id":"deep-22","day":1,"title":"SQL · Parameter Sniffing","concept":"SQL Server may reuse a plan optimized for different parameter cardinalities, causing unstable performance.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What is parameter sniffing?","answer":"SQL Server may reuse a plan optimized for different parameter cardinalities, causing unstable performance.","code":"-- Compare plans for different parameters; tune only after measurements."},{"id":"deep-23","day":1,"title":"SQL · UPSERT Concurrency","concept":"Two transactions can both pass the check; enforce uniqueness in the database and handle conflicts.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why can check-then-insert race?","answer":"Two transactions can both pass the check; enforce uniqueness in the database and handle conflicts.","code":"CREATE UNIQUE INDEX UX_Request ON Requests(CompanyId,ExternalId);"},{"id":"deep-24","day":1,"title":"SQL · OFFSET vs Keyset","concept":"It seeks after a stable last key rather than skipping many rows at high page offsets.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why can keyset pagination scale better?","answer":"It seeks after a stable last key rather than skipping many rows at high page offsets.","code":"WHERE Id > @lastId ORDER BY Id"},{"id":"deep-25","day":1,"title":"SQL · NULL Handling","concept":"No; SQL uses three-valued logic, so test null with IS NULL.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Does NULL = NULL evaluate true?","answer":"No; SQL uses three-valued logic, so test null with IS NULL.","code":"SELECT * FROM Orders WHERE CompletedAt IS NULL;"},{"id":"deep-26","day":1,"title":"SQL · COUNT and JOIN","concept":"One-to-many joins multiply parent rows; count distinct parent keys where appropriate.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why can COUNT(*) over joins overcount orders?","answer":"One-to-many joins multiply parent rows; count distinct parent keys where appropriate.","code":"SELECT COUNT(DISTINCT o.Id) FROM Orders o JOIN OrderItems i ON i.OrderId=o.Id;"},{"id":"deep-27","day":1,"title":"SQL · Query Execution Plan","concept":"A lookup fetches columns missing from a nonclustered index and may become costly for many rows.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What is a key lookup?","answer":"A lookup fetches columns missing from a nonclustered index and may become costly for many rows.","code":"-- Check Actual Execution Plan, logical reads, row estimates."},{"id":"deep-28","day":1,"title":"SQL · Deadlock Retry","concept":"No; retry transient errors such as chosen deadlock victims with backoff and idempotency, not constraints.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Should all database errors be retried?","answer":"No; retry transient errors such as chosen deadlock victims with backoff and idempotency, not constraints.","code":"// classify transient SQL errors before retrying"},{"id":"deep-29","day":1,"title":"SQL · Transactions & External Calls","concept":"Network calls extend lock duration and can cause timeouts/deadlocks; use outbox/event workflows.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why avoid HTTP calls inside DB transactions?","answer":"Network calls extend lock duration and can cause timeouts/deadlocks; use outbox/event workflows.","code":"// Commit DB intent, publish asynchronously via outbox"},{"id":"deep-30","day":1,"title":"Dapper · SQL Injection","concept":"No; use parameters rather than concatenating untrusted values into SQL.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Does Dapper automatically sanitize interpolated SQL?","answer":"No; use parameters rather than concatenating untrusted values into SQL.","code":"await db.QueryAsync(\"SELECT * FROM Users WHERE Id=@Id\",new{Id=id});"},{"id":"deep-31","day":2,"title":"Angular · trackBy / @for track","concept":"Stable identity avoids unnecessary DOM recreation and preserves input state.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why track list items by ID?","answer":"Stable identity avoids unnecessary DOM recreation and preserves input state.","code":"@for(item of items(); track item.id){<div>{{item.name}}</div>}"},{"id":"deep-32","day":2,"title":"Angular · State Management","concept":"Use it when shared complex state, effects and debugging needs justify added structure; simple services/signals may suffice.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"When do you need NgRx?","answer":"Use it when shared complex state, effects and debugging needs justify added structure; simple services/signals may suffice.","code":"// Keep simple local UI state in signals; assess complexity first."},{"id":"deep-33","day":2,"title":"Angular · Error Handling","concept":"Interceptors can handle cross-cutting concerns; components should own context-specific fallback UX.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Where handle global vs local HTTP errors?","answer":"Interceptors can handle cross-cutting concerns; components should own context-specific fallback UX.","code":"return this.http.get('/api/orders').pipe(catchError(()=>of([])));"},{"id":"deep-34","day":2,"title":"Angular · OnPush Mutation Bug","concept":"OnPush often responds to new references or signal notifications; replace state immutably.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why might mutating an array not trigger update?","answer":"OnPush often responds to new references or signal notifications; replace state immutably.","code":"items.set([...items(),newItem]);"},{"id":"deep-35","day":2,"title":"Angular · Memory Leaks","concept":"Long-lived streams subscribed manually without cleanup retain component resources.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What's a typical subscription leak?","answer":"Long-lived streams subscribed manually without cleanup retain component resources.","code":"obs.pipe(takeUntilDestroyed(destroyRef)).subscribe();"},{"id":"deep-36","day":2,"title":"Angular · Accessibility","concept":"Prefer native button semantics with keyboard focus and visible labels; test screen readers.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do you make a custom button accessible?","answer":"Prefer native button semantics with keyboard focus and visible labels; test screen readers.","code":"<button type=\"button\" aria-label=\"Save changes\">Save</button>"},{"id":"deep-37","day":2,"title":"Angular · Authentication Storage","concept":"LocalStorage can be read by injected scripts; evaluate secure HttpOnly cookie strategies and CSRF mitigations.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Should you store long-lived tokens in localStorage?","answer":"LocalStorage can be read by injected scripts; evaluate secure HttpOnly cookie strategies and CSRF mitigations.","code":"// Keep auth decisions server-side."},{"id":"deep-38","day":2,"title":"Angular · XSS Boundaries","concept":"No; it bypasses Angular sanitization protections and must never be used on untrusted content.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Is bypassSecurityTrustHtml safe for user content?","answer":"No; it bypasses Angular sanitization protections and must never be used on untrusted content.","code":"// Prefer interpolation: {{ userText }}"},{"id":"deep-39","day":2,"title":"Angular · Debounced Search","concept":"switchMap unsubscribes from the previous observable, avoiding stale results for typical HttpClient calls.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What happens when the previous request finishes late?","answer":"switchMap unsubscribes from the previous observable, avoiding stale results for typical HttpClient calls.","code":"search$.pipe(debounceTime(300),switchMap(x=>api.search(x)))"},{"id":"deep-40","day":2,"title":"Angular · Unit Testing","concept":"Use Angular HTTP testing utilities to assert method, URL, request body and simulated response.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How would you test an HTTP service?","answer":"Use Angular HTTP testing utilities to assert method, URL, request body and simulated response.","code":"// HttpTestingController.expectOne('/api/orders')"},{"id":"deep-41","day":2,"title":"Redis · Cache Key Design","concept":"To prevent cross-tenant collisions and make schema-based invalidation manageable.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why include tenant and version in cache keys?","answer":"To prevent cross-tenant collisions and make schema-based invalidation manageable.","code":"tenant:12:v2:order:42"},{"id":"deep-42","day":2,"title":"Redis · Cache Stampede","concept":"Use TTL jitter, request coalescing or per-key bounded locks with careful failure handling.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How reduce cache stampede after TTL expiry?","answer":"Use TTL jitter, request coalescing or per-key bounded locks with careful failure handling.","code":"// Add random jitter to TTL on high-volume keys."},{"id":"deep-43","day":2,"title":"Redis · Negative Caching","concept":"To reduce repetitive misses, but avoid stale absence and cache authorization failures separately.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why cache a missing value briefly?","answer":"To reduce repetitive misses, but avoid stale absence and cache authorization failures separately.","code":"// Cache NotFound briefly only if safe for the tenant."},{"id":"deep-44","day":2,"title":"Redis · Redis Persistence","concept":"No; durability depends on configured RDB/AOF persistence and recovery setup.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Does Redis always preserve keys after restart?","answer":"No; durability depends on configured RDB/AOF persistence and recovery setup.","code":"// Check persistence configuration before using Redis for critical state."},{"id":"deep-45","day":2,"title":"Redis · Pub/Sub Durability","concept":"Not from Pub/Sub itself; use durable streams or message brokers if delivery matters.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Can a disconnected subscriber recover Pub/Sub events?","answer":"Not from Pub/Sub itself; use durable streams or message brokers if delivery matters.","code":"// Pub/Sub is ephemeral; Streams retains entries."},{"id":"deep-46","day":2,"title":"Redis · Atomic Operations","concept":"INCR is atomic on a Redis key and avoids lost increments under concurrency.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why prefer atomic INCR to read-modify-write?","answer":"INCR is atomic on a Redis key and avoids lost increments under concurrency.","code":"INCR tenant:12:counter"},{"id":"deep-47","day":2,"title":"Redis · Lock Release","concept":"To prevent a client whose lease expired from removing a lock acquired by another client.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why use an ownership token?","answer":"To prevent a client whose lease expired from removing a lock acquired by another client.","code":"// Compare stored token and delete atomically (Lua)."},{"id":"deep-48","day":2,"title":"Multi-Tenancy · Background Jobs","concept":"Pass validated tenant identity explicitly to job payload, create scoped services and enforce tenant routing.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How should Hangfire jobs resolve tenants?","answer":"Pass validated tenant identity explicitly to job payload, create scoped services and enforce tenant routing.","code":"// Enqueue job with tenantId, not a request-scoped DbContext."},{"id":"deep-49","day":2,"title":"Multi-Tenancy · Tenant Cache","concept":"Different tenants could access or overwrite shared cached data; namespace keys and audit authorization.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What if tenant ID is omitted from Redis key?","answer":"Different tenants could access or overwrite shared cached data; namespace keys and audit authorization.","code":"var key=$\"tenant:{tenantId}:dashboard:{filterHash}\";"},{"id":"deep-50","day":2,"title":"Multi-Tenancy · Authorization","concept":"No. Confirm user membership and server-side allowed tenant mapping before resolving data.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Can a user-provided CompanyId select any tenant DB?","answer":"No. Confirm user membership and server-side allowed tenant mapping before resolving data.","code":"if(!await auth.CanAccessTenant(user,tenantId)) return Results.Forbid();"},{"id":"deep-51","day":2,"title":"Multi-Tenancy · Tenant DB Pooling","concept":"Many distinct connection strings create separate pools and increase resource use.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why can database-per-tenant affect connection pools?","answer":"Many distinct connection strings create separate pools and increase resource use.","code":"// Limit concurrent tenants and monitor pool usage."},{"id":"deep-52","day":2,"title":"Architecture · Repository Pattern","concept":"No; DbContext already exposes repository/unit-of-work behavior; add abstraction only when it creates clear value.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Is repository over EF Core always necessary?","answer":"No; DbContext already exposes repository/unit-of-work behavior; add abstraction only when it creates clear value.","code":"// Avoid creating a generic repository with no domain value."},{"id":"deep-53","day":2,"title":"Architecture · Vertical Slice","concept":"Organize features by end-to-end behavior rather than only technical layers, reducing cross-feature coupling.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What is vertical slice architecture?","answer":"Organize features by end-to-end behavior rather than only technical layers, reducing cross-feature coupling.","code":"// Features/Orders/CreateOrder/Handler.cs"},{"id":"deep-54","day":2,"title":"Architecture · MediatR Pipeline","concept":"Use pipeline behaviors for cross-cutting concerns, keeping handlers focused on business operations.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Where add validation around handlers?","answer":"Use pipeline behaviors for cross-cutting concerns, keeping handlers focused on business operations.","code":"// ValidationBehavior<TRequest,TResponse>"},{"id":"deep-55","day":2,"title":"Architecture · Consistency Models","concept":"When brief lag is tolerable and retry/reconciliation mechanisms ensure convergence.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"When is eventual consistency acceptable?","answer":"When brief lag is tolerable and retry/reconciliation mechanisms ensure convergence.","code":"// Notify user that report generation is processing."},{"id":"deep-56","day":2,"title":"Architecture · Circuit Breaker","concept":"To stop repeated calls to a failing dependency temporarily and allow recovery probes.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why use a circuit breaker?","answer":"To stop repeated calls to a failing dependency temporarily and allow recovery probes.","code":"// Configure with bounded retries, timeouts and metrics."},{"id":"deep-57","day":2,"title":"Security · JWT Revocation","concept":"Use short token lifetimes plus revocation/session strategies where required, balancing scalability.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How can a valid JWT be revoked before expiry?","answer":"Use short token lifetimes plus revocation/session strategies where required, balancing scalability.","code":"// Validate session/version for sensitive operations."},{"id":"deep-58","day":2,"title":"Security · OAuth vs OIDC","concept":"OAuth 2.0 delegates access; OIDC layers identity assertions and ID tokens over OAuth.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How does OIDC differ from OAuth?","answer":"OAuth 2.0 delegates access; OIDC layers identity assertions and ID tokens over OAuth.","code":"// Use OIDC provider for login; validate API access tokens separately."},{"id":"deep-59","day":2,"title":"Security · Refresh Tokens","concept":"Store securely, rotate, detect reuse and revoke compromised token families.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How should refresh tokens be handled?","answer":"Store securely, rotate, detect reuse and revoke compromised token families.","code":"// Never log refresh tokens."},{"id":"deep-60","day":3,"title":"Coding · Valid Parentheses","concept":"Use a stack; push opening characters and match expected closers; O(n) time.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do you validate balanced brackets?","answer":"Use a stack; push opening characters and match expected closers; O(n) time.","code":"var stack=new Stack<char>(); // push openers, pop for closers"},{"id":"deep-61","day":3,"title":"Coding · First Non-Repeating Character","concept":"Count occurrences, then scan again for count one.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do you find the first unique character?","answer":"Count occurrences, then scan again for count one.","code":"var counts=s.GroupBy(c=>c).ToDictionary(g=>g.Key,g=>g.Count());"},{"id":"deep-62","day":3,"title":"Coding · Merge Sorted Arrays","concept":"Advance two pointers and append smaller current element, O(n+m).","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How would you merge two sorted arrays?","answer":"Advance two pointers and append smaller current element, O(n+m).","code":"// while(i<a.Length && j<b.Length) result.Add(a[i]<=b[j]?a[i++]:b[j++]);"},{"id":"deep-63","day":3,"title":"Coding · Group Orders","concept":"Group by customer and sum order totals; ensure correct decimal handling.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do you aggregate order totals per customer?","answer":"Group by customer and sum order totals; ensure correct decimal handling.","code":"var totals=orders.GroupBy(o=>o.CustomerId).Select(g=>new {Id=g.Key,Total=g.Sum(x=>x.Total)});"},{"id":"deep-64","day":3,"title":"Coding · Avoid Shared Context","concept":"DbContext isn't thread-safe; use separate contexts or run operations sequentially.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why is parallelizing EF Core queries on one DbContext wrong?","answer":"DbContext isn't thread-safe; use separate contexts or run operations sequentially.","code":"// Use IDbContextFactory when separate contexts are appropriate."},{"id":"deep-65","day":3,"title":"Coding · Async Error Handling","concept":"Await the combined task, observe exceptions and define whether partial success is acceptable.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do you handle a Task.WhenAll partial failure?","answer":"Await the combined task, observe exceptions and define whether partial success is acceptable.","code":"try{await Task.WhenAll(tasks);}catch(Exception ex){logger.LogError(ex,\"Batch failed\");}"},{"id":"deep-66","day":3,"title":"Coding · SQL Top per Group","concept":"Use ROW_NUMBER partitioned by company and filter rank <= 2.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do you return top two orders per company?","answer":"Use ROW_NUMBER partitioned by company and filter rank <= 2.","code":"WITH q AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY CompanyId ORDER BY Total DESC,Id) rn FROM Orders) SELECT * FROM q WHERE rn<=2;"},{"id":"deep-67","day":3,"title":"Coding · SQL Running Total","concept":"Use SUM() OVER ordered by date and stable key.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do you calculate a running sales total?","answer":"Use SUM() OVER ordered by date and stable key.","code":"SELECT Id,SUM(Total) OVER(ORDER BY CreatedAt,Id ROWS UNBOUNDED PRECEDING) RunningTotal FROM Orders;"},{"id":"deep-68","day":3,"title":"Coding · Endpoint Security","concept":"An attacker can request another tenant; resolve authorized tenant server-side and apply scoping.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What's wrong with trusting CompanyId from the request?","answer":"An attacker can request another tenant; resolve authorized tenant server-side and apply scoping.","code":"// CompanyId must be validated against current user membership."},{"id":"deep-69","day":3,"title":"Coding · Refactoring Large Controller","concept":"Extract feature-specific application services, validation and reusable behavior incrementally with tests.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How would you refactor a 1000-line controller?","answer":"Extract feature-specific application services, validation and reusable behavior incrementally with tests.","code":"// Small controller action delegates to a focused command handler."},{"id":"deep-70","day":3,"title":"Coding · Performance Profiling","concept":"Measure latency breakdown, inspect SQL and I/O, profile allocation, then fix the dominant bottleneck.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How would you debug a slow endpoint in production?","answer":"Measure latency breakdown, inspect SQL and I/O, profile allocation, then fix the dominant bottleneck.","code":"// Trace requestId across API, SQL and cache spans."},{"id":"deep-71","day":3,"title":"Coding · Race Condition","concept":"Both can read same stock; use atomic update with predicate, appropriate transaction and conflict response.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How can two requests oversell inventory?","answer":"Both can read same stock; use atomic update with predicate, appropriate transaction and conflict response.","code":"UPDATE Products SET Stock=Stock-1 WHERE Id=@id AND Stock>0;"},{"id":"deep-72","day":3,"title":"Testing · Testcontainers","concept":"It allows production-like isolated dependencies while retaining repeatability.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"Why use Testcontainers for DB integration tests?","answer":"It allows production-like isolated dependencies while retaining repeatability.","code":"// Spin up ephemeral SQL Server or Redis per test suite."},{"id":"deep-73","day":3,"title":"Testing · Mock vs Stub","concept":"A stub supplies canned responses; a mock verifies expected interactions or calls.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"What's the distinction between a stub and mock?","answer":"A stub supplies canned responses; a mock verifies expected interactions or calls.","code":"// Prefer asserting observable behavior where possible."},{"id":"deep-74","day":3,"title":"System Design · ERP Reports","concept":"Queue jobs, process in background, persist results, expose status and secure downloads.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How would you generate large reports without timing out API requests?","answer":"Queue jobs, process in background, persist results, expose status and secure downloads.","code":"POST /reports -> 202 Accepted; GET /reports/{id}/status"},{"id":"deep-75","day":3,"title":"System Design · Real-Time Dashboard","concept":"Use event notifications with SignalR plus periodic reconciliation and tenant-safe subscriptions.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do you keep a real-time Angular dashboard reliable?","answer":"Use event notifications with SignalR plus periodic reconciliation and tenant-safe subscriptions.","code":"// Event tells UI to refresh authoritative data."},{"id":"deep-76","day":3,"title":"System Design · Multi-Tenant ERP","concept":"Authenticated tenant resolution, tenant-scoped DB access, cache keys, jobs and authorization tests.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How would you isolate tenant data end-to-end?","answer":"Authenticated tenant resolution, tenant-scoped DB access, cache keys, jobs and authorization tests.","code":"// Tenant ID must propagate via explicit validated context."},{"id":"deep-77","day":3,"title":"Behavioral · Production Incident","concept":"Use STAR; cover impact, diagnosis, communication, fix and prevention with honest scope.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do you describe a production incident?","answer":"Use STAR; cover impact, diagnosis, communication, fix and prevention with honest scope.","code":"// Prepare a real incident without inventing metrics."},{"id":"deep-78","day":3,"title":"Behavioral · Performance Improvement","concept":"Describe measured bottleneck, chosen query implementation, validation and observed performance benefit.","ar":"افهم السبب والـ trade-offs في الإجابة، وجرّب المثال عمليًا قبل الانترفيو.","question":"How do you explain EF Core to Dapper optimization?","answer":"Describe measured bottleneck, chosen query implementation, validation and observed performance benefit.","code":"// Compare before/after p95 latency and query IO."}];
const STORE='ahmed-os-interview-progress-v1';let quick=false;
function getProgress(){try{return JSON.parse(localStorage.getItem(STORE)||'{}')}catch{return{}}}
function setStatus(id,value){const p=getProgress();p[id]=value;localStorage.setItem(STORE,JSON.stringify(p));render()}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
function render(){const p=getProgress(),q=document.querySelector('#search').value.trim().toLowerCase(),day=document.querySelector('#day').value,status=document.querySelector('#status').value;const mastered=topics.filter(t=>p[t.id]==='mastered').length;document.querySelector('#counter').textContent=mastered+' / '+topics.length+' mastered';document.querySelector('#progress').style.width=(100*mastered/topics.length)+'%';const matched=topics.filter(t=>(day==='all'||String(t.day)===day)&&(status==='all'||(p[t.id]||'new')===status)&&[t.title,t.concept,t.ar,t.question,t.answer].join(' ').toLowerCase().includes(q));document.querySelector('#cards').innerHTML=matched.length?matched.map(t=>'<article class="card"><small>DAY '+t.day+' · '+escapeHtml(p[t.id]||'Not started')+'</small><h2>'+escapeHtml(t.title)+'</h2><p>'+escapeHtml(t.concept)+'</p>'+(quick?'':'<p class="arabic" lang="ar">'+escapeHtml(t.ar)+'</p>')+'<div class="question"><b>🎤 '+escapeHtml(t.question)+'</b><details><summary>Show ideal answer</summary><blockquote>'+escapeHtml(t.answer)+'</blockquote></details>'+(quick?'':'<details><summary>View code example</summary><div class="code-panel"><div class="code-header"><span>CODE · '+(t.title.includes('Angular')||t.title.includes('TypeScript')?'TypeScript':t.title.includes('SQL')?'SQL':'Example')+'</span><button type="button" class="copy-code" data-code="'+t.id+'">Copy code</button></div><pre><code>'+highlightCode(t.code)+'</code></pre></div></details>')+'</div><div class="actions"><label class="muted" for="s-'+t.id+'">My progress</label><select id="s-'+t.id+'" data-id="'+t.id+'"><option value="new">Not started</option><option value="learning">Learning</option><option value="review">Needs review</option><option value="mastered">Mastered</option></select></div></article>').join(''):'<p class="empty">No topics match these filters.</p>';document.querySelectorAll('select[data-id]').forEach(el=>{el.value=p[el.dataset.id]||'new';el.onchange=()=>setStatus(el.dataset.id,el.value)})}
function highlightCode(s){return escapeHtml(s).replace(/\b(await|async|class|interface|public|private|return|var|const|let|new|if|else|using|from|select|where|int|string|decimal|void|record|override|readonly|SELECT|FROM|WHERE|JOIN|GROUP|BY|ORDER|CREATE|INDEX|ON|AS|BEGIN|END)\b/g,'<span class="code-keyword">$1</span>').replace(/(&quot;[^\n]*?&quot;|&#39;[^\n]*?&#39;)/g,'<span class="code-string">$1</span>')}
document.querySelector('#cards').addEventListener('click',async e=>{const b=e.target.closest('.copy-code');if(!b)return;const t=topics.find(x=>x.id===b.dataset.code);if(!t)return;try{await navigator.clipboard.writeText(t.code);b.textContent='Copied ✓';setTimeout(()=>b.textContent='Copy code',1600)}catch{b.textContent='Copy unavailable'}});
for(const id of ['search','day','status'])document.getElementById(id).addEventListener(id==='search'?'input':'change',render);
document.getElementById('quick').onclick=function(){quick=!quick;this.classList.toggle('active',quick);this.setAttribute('aria-pressed',String(quick));render()};render();